574	/// The Changes section body: the selected workroom's branch, sync state, working-tree changes
575	/// (relative to HEAD), and CI. Reads `store.selectedTargetID` + `store.workroomStatuses`.
576	/// Covers the empty/edge states the design review enumerated: nothing selected, a project
577	/// (non-target), missing directory, still-loading, unknown (probe failed), and clean.
578	struct ChangesPanel: View {
579	  @EnvironmentObject var store: AppStore
580	  private let theme = ThemeService.shared
581	  /// Hard cap on rendered rows so a huge change set can't blow up the list (the underlying
582	  /// output is already byte-capped by `StatusCommandRunner`).
583	  private let renderCap = 200
584	
585	  var body: some View {
586	    Group {
587	      if let sid = store.inspectorTargetID, sid.isStatusable {
588	        content(for: sid)
589	      } else {
590	        inspectorMessage("Select a workroom to see its changes.")
591	      }
592	    }
593	    .frame(maxWidth: .infinity, alignment: .leading)
594	  }
595	
596	  @ViewBuilder
597	  private func content(for sid: SidebarID) -> some View {
598	    let target = store.target(for: sid)
599	    let status = store.workroomStatuses[sid]
600	    if let target, target.isMissing {
601	      inspectorMessage("Directory not found.")
602	    } else if status == nil || status?.lastChecked == nil {
603	      inspectorMessage("Checking\u{2026}")
604	    } else if let status {
605	      // Git and jj render the SAME shape: a branch/bookmark header over a flat change list. jj adds
606	      // the working copy's (`@`) change-id/commit-id/refs + description to the header, since `@` is
607	      // itself a commit. `jjWorkingCopy != nil` is the discriminator — a failed probe leaves it nil,
608	      // so failures fall to the git path (which renders the failure under a branch header, as before).
609	      let name = branchLabel(sid: sid, status: status)
610	      if let workingCopy = status.jjWorkingCopy {
611	        // A jj bookmark that names an ANCESTOR of `@` (rather than `@` itself) is a different thing
612	        // to the reader, and only the resolved `branchForCI` — not the `detached` fallback — can be
613	        // one, so the distinction is drawn here where the status is in hand.
614	        let ancestor =
615	          (status.branchForCI.map { !$0.isEmpty } ?? false) && !workingCopy.refs.contains(name)
616	        jjContent(name: name, workingCopy: workingCopy, ancestorBookmark: ancestor)
617	      } else {
618	        gitContent(name: name, status: status)
619	      }
620	    }
621	  }
