623	  /// Git repos: the branch header over the working-tree change list (or clean/failure). CI is
624	  /// GitHub-derived, so it lives in the Pull Request section — not here.
625	  @ViewBuilder
626	  private func gitContent(name: String, status: WorkroomStatus) -> some View {
627	    VStack(alignment: .leading, spacing: 10) {
628	      changesHeader(name: name, meta: nil, identifier: nil)
629	      Divider()
630	      if let failure = status.failure {
631	        inspectorMessage(failureText(failure))
632	      } else if status.isClean {
633	        cleanState
634	      } else {
635	        fileList(status.changedFiles ?? [], source: .gitWorktree)
636	      }
637	    }
638	    .padding(12)
639	  }
