641	  /// jj repos: the working copy (`@`) — its bookmark/branch name plus, because `@` is itself a
642	  /// commit, its change-id/commit-id/refs and description — over the flat change list, mirroring
643	  /// `gitContent`. The working copy's parent (`@-`) is no longer shown here; the History panel now
644	  /// surfaces it.
645	  @ViewBuilder
646	  private func jjContent(name: String, workingCopy: JJCommitChanges, ancestorBookmark: Bool)
647	    -> some View
648	  {
649	    VStack(alignment: .leading, spacing: 10) {
650	      changesHeader(
651	        name: name, meta: workingCopy, identifier: "changes.workingCopy",
652	        ancestorBookmark: ancestorBookmark)
653	      Divider()
654	      if workingCopy.files.isEmpty {
655	        cleanState
656	      } else {
657	        fileList(workingCopy.files, source: .jjWorkingCopy)
658	      }
659	    }
660	    .padding(12)
661	  }
