663	  /// The shared Changes header: the branch/bookmark name, plus (for jj, whose working copy is a
664	  /// commit) its change-id (purple) / commit-id (blue) / the refs the name pill doesn't already show,
665	  /// and the description line. `meta == nil` (git) renders just the name — git's working tree isn't a
666	  /// commit, so it carries no refs or message. `ancestorBookmark` says the name pill points at an
667	  /// ancestor of `@` rather than `@` itself, which only its tooltip distinguishes. `identifier`
668	  /// combines the header into one a11y element (jj only; the panel's render sentinel).
669	  @ViewBuilder
670	  private func changesHeader(
671	    name: String, meta: JJCommitChanges?, identifier: String?, ancestorBookmark: Bool = false
672	  ) -> some View {
673	    // jj's `branch_for_ci` (the left pill) is the first bookmark in `::@` log order, and `@` is the
674	    // first commit that walk emits — so whenever `@` itself is bookmarked, the left pill's name is
675	    // by construction also in `meta.refs`, and rendering both put ONE bookmark on screen as two
676	    // identical capsules. Chip only what the left pill isn't already showing. The case the left
677	    // pill exists for is untouched: when `@` carries no bookmark it names an ancestor's and `refs`
678	    // is empty. A multi-bookmark `@` still reads right — left pill = the alphabetically first,
679	    // chips = the rest.
680	    let extraRefs = (meta?.refs ?? []).filter { $0 != name }
681	    VStack(alignment: .leading, spacing: 2) {
682	      HStack(alignment: .firstTextBaseline, spacing: 6) {
683	        // The branch/bookmark the working copy is on, as the same gray pill the History list rows and
684	        // the changeset detail header give a ref — it names the same kind of thing, so it shouldn't
685	        // read as a bold title in one surface and a capsule in the others. Truncates in the MIDDLE
686	        // (unlike the ref pills beside it): a long branch name's distinguishing part is often its
687	        // tail (`joel/history-refs-pill`), so tail-truncating it would hide what tells it apart.
688	        Text(name).font(.caption)
689	          .lineLimit(1).truncationMode(.middle)
690	          .padding(.horizontal, 5).padding(.vertical, 1)
691	          .background(.quaternary, in: Capsule())
692	          // NOT "nearest": `branch_for_ci` is the first bookmark in `::@`'s LOG order, which at a
693	          // merge can be further away in the graph than one on another parent (see
694	          // `first_bookmark_in_log_order`'s doc). It is the first one walking down History, so that's
695	          // what the tooltip says.
696	          .help(ancestorBookmark ? "First ancestor bookmark in history" : "Bookmark / branch")
697	        if let meta {
698	          if let changeID = meta.changeID {
699	            Text(changeID).font(.system(.callout, design: .monospaced))
700	              .foregroundStyle(.purple).help("Change ID")
701	          }
702	          if let commitID = meta.commitID {
703	            Text(commitID).font(.system(.callout, design: .monospaced))
704	              .foregroundStyle(.blue).help("Commit ID")
705	          }
706	          // The same gray capsules the History list rows and changeset header use, one step down
707	          // from the ids beside them (`.caption` under `.callout`, as the list's `.caption2` sits
708	          // under its `.caption`) so the pill doesn't outweigh this header's larger type.
709	          ForEach(extraRefs, id: \.self) { ref in
710	            Text(ref).font(.caption)
711	              .lineLimit(1).truncationMode(.tail)
712	              .padding(.horizontal, 5).padding(.vertical, 1)
713	              .background(.quaternary, in: Capsule())
714	              .help("Bookmark / branch")
715	          }
716	        }
717	        Spacer(minLength: 0)
718	      }
719	      if let meta {
720	        if let desc = meta.description {
721	          Text(desc).font(.callout).foregroundStyle(.primary)
722	            .lineLimit(1).truncationMode(.tail)
723	        } else {
724	          Text("(no description set)").font(.footnote).foregroundStyle(.tertiary).lineLimit(1)
725	        }
726	      }
727	    }
728	    .frame(maxWidth: .infinity, alignment: .leading)
729	    .modifier(CombinedA11y(identifier: identifier))
730	  }
731	
732	  /// The bold header name for both VCS kinds: the branch/bookmark the working copy is on (`branchForCI`
733	  /// — for jj, the nearest ancestor bookmark). Falls back to the root row's resolved ref for a project
734	  /// root, else `detached`.
735	  private func branchLabel(sid: SidebarID, status: WorkroomStatus) -> String {
736	    if let branch = status.branchForCI, !branch.isEmpty { return branch }
