588	///
589	/// `base_ignores` chains the global + repo-local excludes (see `base_ignores`); `max_new_file_size`
590	/// matches the jj CLI default (1 MiB) so a status refresh can't hash/store an arbitrarily huge
591	/// untracked file.
592	fn snapshot_working_copy(root: &Path) -> model::Result<(Workspace, Arc<ReadonlyRepo>)> {
593	    let settings = UserSettings::from_config(StackedConfig::with_defaults()).map_err(io)?;
594	    let mut workspace = Workspace::load(
595	        &settings,
596	        root,
597	        &StoreFactories::default(),
598	        &default_working_copy_factories(),
599	    )
600	    .map_err(workspace_load_err)?;
601	    let mut repo = pollster::block_on(workspace.repo_loader().load_at_head()).map_err(io)?;
602	
603	    let wc_name = workspace.workspace_name().to_owned();
604	    let Some(wc_commit_id) = repo.view().get_wc_commit_id(&wc_name).cloned() else {
605	        // No working-copy commit (e.g. a bare/foreign workspace) — nothing to snapshot.
606	        return Ok((workspace, repo));
607	    };
608	    let mut wc_commit = repo.store().get_commit(&wc_commit_id).map_err(io)?;
609	
610	    // Fail fast when someone else holds the working-copy lock (see `lock_is_held`) — a blocking
611	    // `flock` here would pin this thread, and a gate slot, for as long as the other process runs.
612	    if lock_is_held(&workspace) {
613	        return Err(VcsError::LockContention);
614	    }
615	
616	    let mut locked_ws = pollster::block_on(workspace.start_working_copy_mutation()).map_err(io)?;
617	
618	    // jj's own staleness guard, which every `jj` command runs and this read used to skip. The lock is
619	    // taken AFTER the repo was loaded, so between the two another process (the user's `jj` in a
620	    // terminal, or a sibling *workspace* of the same repo — i.e. another workroom — rewriting this
621	    // `@`) can have moved things underneath us. Snapshotting anyway would write a new `@` from a base
622	    // that no longer describes this working copy, which is how work gets clobbered.
623	    let freshness = pollster::block_on(WorkingCopyFreshness::check_stale(
624	        locked_ws.locked_wc(),
625	        &wc_commit,
626	        &repo,
627	    ))
628	    .map_err(io)?;
629	    match freshness {
630	        WorkingCopyFreshness::Fresh => {}
