import Foundation

/// The commit sheet's target, carried the way `PendingVCSAction` carries a confirmation's.
///
/// `.sheet(item:)` keys on `id`, so the sheet's `@State` — the draft and the selection — is rebuilt
/// per target and can never leak from one workroom into another.
struct PendingCommit: Identifiable, Equatable, Sendable {
  let sid: SidebarID
  /// `"git"` or `"jj"`. Decides whether per-file selection is offered at all and which second verb
  /// the menu carries.
  let vcs: String
  var id: String { "\(vcs)-\(sid.hashValue)" }
}

/// The commit sheet's pure logic: what the message is, what is selected, and what the button says.
///
/// Separated from the view for the reason `ChangeBadge` and `VCSSyncPresenter` are: these are
/// many-case decisions that drift silently, and none of them is reachable from a test through
/// SwiftUI. The view holds state and renders; every rule below is decided here.
enum CommitDraft {

  /// Compose the message git or jj will record.
  ///
  /// Summary and body are joined by a BLANK line, which is the convention every tool downstream
  /// relies on to split a subject from its body. Both halves are trimmed, and an empty body yields a
  /// subject-only message with no trailing newlines for `--cleanup` to strip.
  static func message(summary: String, body: String) -> String {
    let subject = summary.trimmingCharacters(in: .whitespacesAndNewlines)
    let detail = body.trimmingCharacters(in: .whitespacesAndNewlines)
    return detail.isEmpty ? subject : "\(subject)\n\n\(detail)"
  }

  /// Split a stored message back into the two fields, for prefilling from jj's `@` description.
  ///
  /// The first line is the summary and everything after the first blank line is the body. Used
  /// against the FULL description — `JJCommitChanges.description` carries only the first line, so
  /// prefilling from that and describing again would silently discard the body.
  static func split(message: String) -> (summary: String, body: String) {
    let normalized = message.replacingOccurrences(of: "\r\n", with: "\n")
    var lines = normalized.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    guard !lines.isEmpty else { return ("", "") }
    let summary = lines.removeFirst().trimmingCharacters(in: .whitespaces)
    let body = lines.joined(separator: "\n").trimmingCharacters(in: .whitespacesAndNewlines)
    return (summary, body)
  }

  /// The files a commit would record, given what the user has EXCLUDED.
  ///
  /// Deselections are stored, never selections, and this is the reason. Coding agents run in this
  /// app's own embedded terminals and write files continuously, so the change set moves underneath
  /// an open dialog. With a set of *selected* paths there are only two possible behaviours when a new
  /// path appears — include it silently (committing a file nobody reviewed, which is the exact defect
  /// per-file selection exists to prevent) or reset the selection (throwing away the user's
  /// deliberate exclusions). Storing exclusions makes a new file arrive checked, which is the honest
  /// default, and makes an exclusion survive every refresh.
  ///
  /// A path that vanishes from the change set drops out on its own, so the excluded set never needs
  /// pruning.
  static func selected(from files: [ChangedFile], excluding excluded: Set<String>) -> [ChangedFile] {
    files.filter { !excluded.contains($0.path) }
  }

  /// The primary button's label. Names the count so what is about to be recorded is never implicit —
  /// once the list scrolls, "Commit" alone is an unverifiable claim.
  static func commitLabel(selectedCount: Int, vcs: String) -> String {
    // jj commits the whole change and offers no per-file selection, so a count would imply a choice
    // that isn't on offer.
    guard vcs != "jj" else { return "Commit" }
    switch selectedCount {
    case 1: return "Commit 1 file"
    default: return "Commit \(selectedCount) files"
    }
  }

  /// Why Commit is unavailable, as a sentence, or nil when it is available.
  ///
  /// Returned as text rather than a Bool because these must render as a persistent inline line: four
  /// different blocked states explained only by a tooltip would be invisible to anyone who doesn't
  /// hover a control that already looks dead, and unavailable to VoiceOver entirely.
  static func blockedReason(
    vcs: String, summary: String, selectedCount: Int, totalCount: Int, conflicted: Bool,
    sequencer: String?
  ) -> String? {
    if let sequencer {
      return "A \(sequencer) is in progress. Finish it in the terminal before committing."
    }
    // git refuses to commit unmerged paths outright. jj records conflicts inside commits and would
    // happily accept this, but "Commit" reading as "done" over unresolved conflicts is a UX decision,
    // not a capability one — so both backends say the same thing.
    if conflicted {
      return "Some files still have unresolved conflicts. Resolve them first."
    }
    if totalCount == 0 && vcs != "jj" {
      return "Nothing has changed in this workroom yet."
    }
    if vcs != "jj" && selectedCount == 0 {
      return "Select at least one file to commit."
    }
    if summary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      return "Write a summary to describe this change."
    }
    return nil
  }
}

import SwiftUI

/// Record a commit: what will be included, the message, and the failure when there is one.
///
/// **Why a dialog rather than a box in the Changes pane.** Measured against the pane it would have
/// lived in: the composer is ~152pt and `InspectorPanePolicy.expandedMinHeight` leaves 86pt of body,
/// so at the pane's own drag floor the Commit button was below the fold. At a default third of a
/// 900pt window it left two file rows for git and one for jj — for a list whose entire job is letting
/// you decide whether committing is safe. Pinning it would also have meant switching Changes to fill
/// hosting, which disables the documented compress-and-scroll valve (`InspectorSplitView`), so a
/// short window would clip the button rather than scroll to it.
///
/// The dialog also deletes state rather than managing it: the draft and the selection live here for
/// the sheet's lifetime, so there is no per-workroom draft store to prune on delete, no recycled
/// workroom name inheriting last week's message, and no two windows racing one `Defaults` dictionary
/// (`AppStore` is per window).
///
/// The cost, accepted: this covers the diff you were reading.
struct CommitSheet: View {
  let pending: PendingCommit
  let onDismiss: () -> Void

  @EnvironmentObject var store: AppStore
  private let theme = ThemeService.shared

  @State private var summary = ""
  @State private var body_ = ""
  /// EXCLUSIONS, not selections — see `CommitDraft.selected(from:excluding:)`. A file written while
  /// this sheet is open arrives checked; a file the user unticked stays unticked.
  @State private var excluded: Set<String> = []
  @State private var phase: Phase = .editing
  @State private var prefilled = false
  @FocusState private var summaryFocused: Bool

  private enum Phase: Equatable {
    case editing
    case committing
    case failed(VCSFailureDialog)
  }

  private var isJJ: Bool { pending.vcs == "jj" }
  private var status: WorkroomStatus? { store.workroomStatuses[pending.sid] }

  /// Every changed file, from whichever shape this backend reports.
  private var files: [ChangedFile] {
    guard let status else { return [] }
    if let workingCopy = status.jjWorkingCopy { return workingCopy.files }
    return status.changedFiles ?? []
  }

  private var selectedFiles: [ChangedFile] {
    // jj commits the whole change, so the exclusion set is never applied to it.
    isJJ ? files : CommitDraft.selected(from: files, excluding: excluded)
  }

  private var blockedReason: String? {
    CommitDraft.blockedReason(
      vcs: pending.vcs, summary: summary, selectedCount: selectedFiles.count,
      totalCount: files.count, conflicted: status?.conflicted ?? false, sequencer: nil)
  }

  var body: some View {
    VStack(alignment: .leading, spacing: 14) {
      header
      fileSection
      messageSection
      if case .failed(let dialog) = phase { CommitFailureNotice(dialog: dialog) }
      Divider()
      buttons
    }
    .padding(20)
    .frame(width: 520)
    .onAppear(perform: prefill)
    // `children: .contain` is load-bearing: an identifier on a plain container makes SwiftUI treat it
    // as ONE element and swallow everything inside, which XCUITest then cannot reach. Same lesson
    // `VCSFailureSheet` records.
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("commit.sheet")
  }

  private var header: some View {
    HStack(alignment: .firstTextBaseline, spacing: 8) {
      Text(isJJ ? "Describe this change" : "Commit changes")
        .font(.headline)
        .accessibilityIdentifier("commit.title")
      Spacer(minLength: 0)
      if !files.isEmpty {
        Text(countCaption)
          .font(.caption)
          .foregroundStyle(.secondary)
          .accessibilityIdentifier("commit.count")
      }
    }
  }

  private var countCaption: String {
    isJJ
      ? "\(files.count) file\(files.count == 1 ? "" : "s") in this change"
      : "\(selectedFiles.count) of \(files.count) file\(files.count == 1 ? "" : "s")"
  }

  // MARK: Files

  @ViewBuilder private var fileSection: some View {
    if files.isEmpty {
      // jj can legitimately describe an empty change, so this is a note rather than a blocker there.
      Text(
        isJJ
          ? "This change has no file changes yet. You can still give it a message."
          : "Nothing has changed in this workroom yet.")
        .font(.callout).foregroundStyle(.secondary)
        .frame(maxWidth: .infinity, alignment: .leading)
    } else {
      VStack(alignment: .leading, spacing: 6) {
        if !isJJ { selectAllRow }
        ScrollView {
          VStack(alignment: .leading, spacing: 2) {
            ForEach(files) { file in
              CommitFileRow(
                file: file, showsCheckbox: !isJJ,
                isIncluded: !excluded.contains(file.path),
                toggle: { toggle(file) },
                only: { excluded = Set(files.map(\.path)).subtracting([file.path]) })
            }
          }
          .padding(.vertical, 2)
        }
        .frame(maxHeight: 200)
        .background(RoundedRectangle(cornerRadius: 6).fill(.quaternary.opacity(0.4)))
        if isJJ {
          Text("jj commits the whole change. Splitting isn’t supported yet.")
            .font(.caption).foregroundStyle(.tertiary)
        }
      }
    }
  }

  /// The bulk affordance. Without it, "commit only this file" — an extremely common intent — costs
  /// one click per unwanted file.
  private var selectAllRow: some View {
    let allIncluded = excluded.isEmpty
    return Button {
      excluded = allIncluded ? Set(files.map(\.path)) : []
    } label: {
      HStack(spacing: 6) {
        Image(
          systemName: allIncluded
            ? "checkmark.square.fill" : (selectedFiles.isEmpty ? "square" : "minus.square.fill")
        )
        .font(.callout)
        .foregroundStyle(allIncluded || !selectedFiles.isEmpty ? Color.accentColor : .secondary)
        .frame(width: 14)
        Text(allIncluded ? "Deselect all" : "Select all").font(.caption)
        Spacer(minLength: 0)
      }
      .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .help("Include or exclude every changed file")
    .accessibilityIdentifier("commit.selectAll")
  }

  private func toggle(_ file: ChangedFile) {
    if excluded.contains(file.path) {
      excluded.remove(file.path)
    } else {
      excluded.insert(file.path)
    }
  }

  // MARK: Message

  private var messageSection: some View {
    VStack(alignment: .leading, spacing: 8) {
      TextField("Summary", text: $summary)
        .textFieldStyle(.roundedBorder)
        .focused($summaryFocused)
        .accessibilityIdentifier("commit.summary")
        .onSubmit { if blockedReason == nil { commit(mode: .commit) } }
      ZStack(alignment: .topLeading) {
        // SwiftUI's TextEditor has no placeholder, so it is drawn behind. `allowsHitTesting(false)`
        // keeps the click through to the editor.
        if body_.isEmpty {
          Text("Description (optional)")
            .font(.body)
            .foregroundStyle(.tertiary)
            .padding(.horizontal, 5)
            .padding(.vertical, 8)
            .allowsHitTesting(false)
        }
        TextEditor(text: $body_)
          .font(.body)
          .scrollContentBackground(.hidden)
          .frame(minHeight: 80, maxHeight: 140)
          .padding(2)
          .accessibilityIdentifier("commit.description")
      }
      .background(RoundedRectangle(cornerRadius: 6).fill(.quaternary.opacity(0.4)))
      .overlay(RoundedRectangle(cornerRadius: 6).stroke(theme.tokens.border, lineWidth: 1))
    }
  }

  // MARK: Buttons

  private var buttons: some View {
    HStack(spacing: 8) {
      // A persistent line, never a tooltip: nobody hovers a button that looks dead, and a tooltip is
      // unreachable by keyboard and invisible to VoiceOver.
      if let blockedReason, phase == .editing {
        Text(blockedReason)
          .font(.caption)
          .foregroundStyle(.secondary)
          .fixedSize(horizontal: false, vertical: true)
          .accessibilityIdentifier("commit.blocked")
      }
      if phase == .committing {
        ProgressView().controlSize(.small)
        Text("Running hooks…").font(.caption).foregroundStyle(.secondary)
      }
      Spacer(minLength: 0)
      Button("Cancel") { onDismiss() }
        .keyboardShortcut(.cancelAction)
        .accessibilityIdentifier("commit.cancel")
      secondaryMenu
      Button(CommitDraft.commitLabel(selectedCount: selectedFiles.count, vcs: pending.vcs)) {
        commit(mode: .commit)
      }
      .keyboardShortcut(.defaultAction)
      .buttonStyle(.borderedProminent)
      .disabled(blockedReason != nil || phase == .committing)
      .help(isJJ ? "Describe this change and start a new one on top" : "Commit the selected files")
      .accessibilityIdentifier("commit.commit")
    }
  }

  /// The backend's second verb. Labelled by OUTCOME, with the command named only in the help text —
  /// the product goal is that you don't need to know jj's vocabulary to use this.
  @ViewBuilder private var secondaryMenu: some View {
    Menu {
      if isJJ {
        Button("Set Message Only") { commit(mode: .describe) }
          .help("Name the current change and stay on it (jj describe)")
      } else {
        Button("Amend Last Commit") { commit(mode: .amendMessage) }
          .help("Replace the last commit’s message. Nothing else about it changes.")
      }
    } label: {
      Image(systemName: "ellipsis")
    }
    .menuStyle(.button)
    .menuIndicator(.hidden)
    .fixedSize()
    .disabled(phase == .committing || summary.trimmingCharacters(in: .whitespaces).isEmpty)
    .help("Other ways to record this message")
    .accessibilityIdentifier("commit.moreActions")
  }

  // MARK: Actions

  /// Prefill from jj's `@` description, once. git has nothing to prefill from.
  ///
  /// Reads the FULL description rather than `JJCommitChanges.description`, which is only its first
  /// line — prefilling the summary from that and then pressing Set Message Only would silently
  /// discard the body the user wrote earlier.
  private func prefill() {
    summaryFocused = true
    guard isJJ, !prefilled else { return }
    prefilled = true
    guard let item = store.statusWorkItem(for: pending.sid) else { return }
    Task {
      let result = await StatusCommandRunner().run(
        "jj", CLIVCSWriter.jjDescriptionArgs(), in: item.path, timeout: 5)
      guard result.ok else { return }
      let existing = CommitDraft.split(message: result.stdout)
      // Never clobber something typed while the read was in flight.
      if summary.isEmpty && body_.isEmpty {
        summary = existing.summary
        body_ = existing.body
      }
    }
  }

  private func commit(mode: VCSCommitMode) {
    guard phase != .committing else { return }
    phase = .committing
    let request = VCSCommitRequest(
      message: CommitDraft.message(summary: summary, body: body_),
      files: mode == .amendMessage ? [] : selectedFiles, mode: mode)
    store.performCommit(request, on: pending.sid) { result in
      switch result {
      case .ok:
        onDismiss()
      case .committedThenFailed(_, let detail):
        // The commit LANDED. Closing would be a lie by omission, and offering a retry would create a
        // second commit, so the sheet stays up saying exactly that.
        phase = .failed(
          VCSFailureDialog(
            title: "Committed, but something afterwards failed",
            message:
              "The commit was recorded. A step that runs after it — usually a post-commit hook — "
              + "then failed. Do not commit again; the change is already saved.",
            details: detail, recovery: nil, lockPath: nil))
      case .failed(let failure):
        phase = .failed(VCSSyncPresenter.commitFailureDialog(failure, mode: mode))
      }
    }
  }
}

/// One changed file, with its inclusion checkbox.
///
/// The checkbox is an SF Symbol in a 14pt slot rather than a `Toggle` on purpose: the row aligns on
/// `.firstTextBaseline` so the directory text sits on the filename's baseline, and a `Toggle` has no
/// text baseline to align to — it would sit visibly high against the change letter beside it. Same
/// glyph size and same slot width as that letter, so both share a baseline by construction.
private struct CommitFileRow: View {
  let file: ChangedFile
  let showsCheckbox: Bool
  let isIncluded: Bool
  let toggle: () -> Void
  let only: () -> Void

  var body: some View {
    HStack(alignment: .firstTextBaseline, spacing: 6) {
      if showsCheckbox {
        Button(action: toggle) {
          Image(systemName: isIncluded ? "checkmark.square.fill" : "square")
            .font(.callout)
            .foregroundStyle(isIncluded ? Color.accentColor : .secondary)
            .frame(width: 14)
        }
        .buttonStyle(.plain)
        .help(isIncluded ? "Exclude this file from the commit" : "Include this file in the commit")
        .accessibilityIdentifier("commit.file.check.\(file.path)")
      }
      Text(ChangeBadge.letter(for: file.change))
        .font(.system(.caption, design: .monospaced))
        .foregroundStyle(ChangeBadge.color(for: file.change))
        .frame(width: 14)
        .accessibilityHidden(true)
      let parts = ChangesPanel.splitPath(file.path)
      Text(parts.name).font(.callout).lineLimit(1).truncationMode(.middle)
      if !parts.dir.isEmpty {
        Text(parts.dir)
          .font(.caption2).foregroundStyle(.tertiary)
          .lineLimit(1).truncationMode(.head)
      }
      Spacer(minLength: 0)
    }
    .padding(.horizontal, 8)
    .padding(.vertical, 2)
    // Excluded rows dim their CONTENT rather than taking a background: the accent background already
    // means "this row's diff is the focused tab" in the Changes panel, and two selection meanings
    // sharing one visual is how a user learns to distrust both.
    .opacity(showsCheckbox && !isIncluded ? 0.45 : 1)
    .contentShape(Rectangle())
    .accessibilityElement(children: .combine)
    .accessibilityLabel(
      "\(ChangeBadge.word(for: file.change)) \(file.path)"
        + (showsCheckbox ? (isIncluded ? ", included" : ", excluded") : ""))
    .contextMenu {
      if showsCheckbox {
        Button("Commit Only This File", action: only)
        Button(isIncluded ? "Exclude This File" : "Include This File", action: toggle)
      }
    }
  }
}

/// A commit failure, inline. Same content as `VCSFailureSheet` — a sheet cannot present another
/// sheet over itself, and the draft has to stay on screen because it survives the failure.
private struct CommitFailureNotice: View {
  let dialog: VCSFailureDialog
  @State private var showDetails = false

  var body: some View {
    VStack(alignment: .leading, spacing: 8) {
      HStack(alignment: .top, spacing: 8) {
        Image(systemName: "exclamationmark.triangle.fill")
          .foregroundStyle(.orange)
          .accessibilityHidden(true)
        VStack(alignment: .leading, spacing: 4) {
          Text(dialog.title).font(.subheadline.weight(.semibold))
          Text(dialog.message)
            .font(.caption).foregroundStyle(.secondary)
            .textSelection(.enabled)
            .fixedSize(horizontal: false, vertical: true)
        }
      }
      // The hook's own output is the most useful text in the whole taxonomy — 40 lines of eslint
      // naming file and line — so it gets a scroll pane and selectable text, not a truncated line.
      if let details = dialog.details {
        DisclosureGroup(isExpanded: $showDetails) {
          ScrollView {
            Text(details)
              .font(.system(.caption2, design: .monospaced))
              .textSelection(.enabled)
              .frame(maxWidth: .infinity, alignment: .leading)
              .padding(6)
          }
          .frame(maxHeight: 120)
          .background(RoundedRectangle(cornerRadius: 5).fill(.quaternary.opacity(0.5)))
        } label: {
          Text("Output").font(.caption.weight(.semibold))
        }
        .accessibilityIdentifier("commit.failure.detailsToggle")
      }
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    .padding(10)
    .background(RoundedRectangle(cornerRadius: 6).fill(Color.orange.opacity(0.08)))
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("commit.failure")
  }
}

